def comb_sort(nums):
    gap = len(nums)
    shrink = 1.3
    sorted_numbers = False

    while not sorted_numbers:
        gap = gap // shrink
        if gap < 1:
            gap = 1
            sorted_numbers = True

        new_sorted = True
        for i in range(len(nums) - gap):
            if nums[i] > nums[i + gap]:
                nums[i], nums[i + gap] = nums[i + gap], nums[i]
                new_sorted = False

        if new_sorted:
            sorted_numbers = True

    return nums
```

