def is_majority(arr, n, x):
    if n == 0:
        return False

    # Since the array is sorted, we can find the first and last occurrence of x using binary search.
    # Then calculate the count of x in the array.

    def binary_search_first(arr, x):
        left, right = 0, n - 1
        first_occurrence = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                first_occurrence = mid
                right = mid - 1
            elif arr[mid] > x:
                right = mid - 1
            else:
                left = mid + 1
        return first_occurrence

    def binary_search_last(arr, x):
        left, right = 0, n - 1
        last_occurrence = -1
        while left <= right:
            mid = (left + right) // 2
            if arr[mid] == x:
                last_occurrence = mid
                left = mid + 1
            elif arr[mid] > x:
                right = mid - 1
            else:
                left = mid + 1
        return last_occurrence

    first = binary_search_first(arr, x)
    if first == -1:
        return False  # x is not present in the array

    last = binary_search_last(arr, x)
    count = last - first + 1

    return count > n // 2
