def shell_sort(my_list):
    n = len(my_list)
    gaps = [n // 2]
    while gaps[0] > 0:
        gaps.insert(0, gaps[0] // 2)

    for gap in gaps:
        for i in range(gap, n):
            temp = my_list[i]
            j = i
            while j >= gap and my_list[j - gap] > temp:
                my_list[j] = my_list[j - gap]
                j -= gap
            my_list[j] = temp
    return my_list
```

